import {drawCityReward} from './reward-models.js?v=scenario-dialog-text-1';
import {REWARDS,rewardCondition} from './rewards.js?v=scenario-dialog-text-1';
export function showRewards({city,dialog,close,setTool}){const c=city(),fmt=n=>'§'+n.toLocaleString();dialog('Rewards · gifts for your city',`<p>Fulfill each requirement for consecutive simulation months to receive an offer. Scenario events can also grant a reward before its normal requirements are met. Earned rewards remain available until you are ready to place them. You can have one of each; after demolition or destruction you can rebuild.</p>${Object.entries(REWARDS).map(([k,d])=>{const earned=c.rewards.earned[k]!==null,placed=c.tiles.some(t=>t.type===k);return `<div class="milestone"><small>${placed?'PLACED':earned?'AVAILABLE TO PLACE':rewardCondition(c,k)?'REQUIREMENTS MET · KEEP IT UP':'WORKING TOWARD THIS'}</small><h3>${d.name}</h3><canvas id="rewardPreview-${k}" width="512" height="512" role="img" aria-label="${d.name} building preview" style="display:block;width:min(100%,280px);height:auto;margin:auto"></canvas><button data-reward-rotate="${k}" aria-label="Rotate ${d.name} preview">Rotate preview</button><p>${d.requirement}</p><p>${earned?`Earned in city month ${c.rewards.earned[k]}.`:`Progress: ${c.rewards.streaks[k]} / ${d.months} consecutive months.`}</p><p>${d.size} × ${d.size} level land · ${fmt(d.cost)} construction · ${fmt(d.upkeep)}/month upkeep. Needs electricity and a nearby road.</p><p>${k==='mayorHouse'?'A gift from your residents that improves nearby land value and happiness.':k==='stadium'?'An operating stadium adds 20 residential demand and improves nearby amenities.':'An operating university adds 10 to the education target and 10 commercial demand, while improving nearby amenities.'}</p><button data-reward="${k}" ${!earned||placed?'disabled':''}>Place ${d.name}</button></div>`;}).join('')}<p class="fine">Unlock thresholds, prices, footprints and benefits are reconstruction choices. This is the first reward set; the original full reward and business-opportunity catalog remains unfinished.</p>`);const rotations={};for(const k of Object.keys(REWARDS)){rotations[k]=0;const canvas=document.getElementById('rewardPreview-'+k),ctx=canvas.getContext('2d');const draw=()=>{ctx.clearRect(0,0,512,512);drawCityReward(ctx,k,rotations[k],256,320,512);};document.querySelector('[data-reward-rotate="'+k+'"]').onclick=()=>{rotations[k]=(rotations[k]+1)%4;draw();};draw();}document.querySelectorAll('[data-reward]').forEach(b=>b.onclick=()=>{setTool(b.dataset.reward);close();});}
